const CACHE='senda-web-2026-09-26-2';
const SCENES=['faith','love','hope','prayer','wisdom','justice','forgiveness'].flatMap(theme=>['', '_alt', '_alt2'].map(suffix=>`/images/theme_${theme}${suffix}.webp`));
const SHELL=['/','/index.html','/app.js','/plan.js','/catalog.js','/portable.js','/generator.worker.js','/styles.css','/manifest.webmanifest','/favicon.svg','/icon-192.png','/icon-512.png',...SCENES];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(SHELL)).then(()=>self.skipWaiting())));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(names=>Promise.all(names.filter(n=>n!==CACHE).map(n=>caches.delete(n)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{const request=event.request;if(request.method!=='GET'||new URL(request.url).origin!==self.location.origin)return;const isCode=/\.(?:html|js|css|webmanifest)$/.test(new URL(request.url).pathname)||new URL(request.url).pathname==='/';event.respondWith((async()=>{const cache=await caches.open(CACHE);if(isCode){try{const response=await fetch(request);if(response.ok)cache.put(request,response.clone());return response;}catch{return await cache.match(request)||await cache.match('/index.html');}}const hit=await cache.match(request);if(hit)return hit;const response=await fetch(request);if(response.ok)cache.put(request,response.clone());return response;})());});
